/**
 * Test flow for moveAttachment action
 * Demonstrates moving an attachment from one record to another
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testMoveAttachment = Flow(
    {
        $id: Now.ID['test_move_attachment_flow'],
        name: 'Test Move Attachment',
        description: 'Tests the moveAttachment core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_move_attachment_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        // Create a target incident
        const targetIncident = wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_move_attachment_create_target'] },
            {
                table_name: 'incident',
                values: TemplateValue({
                    short_description: 'Target Incident',
                    priority: 3,
                }),
            }
        )

        const result = wfa.action(
            action.core.moveAttachment,
            { $id: Now.ID['test_move_attachment_action'] },
            {
                source_attachment_record: 'sample_attachment_sys_id',
                target_record: wfa.dataPill(targetIncident.record, 'reference'),
                table: 'incident',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_move_attachment_log'] },
            {
                log_level: 'info',
                log_message: `moveAttachment outputs: attachment_id=${wfa.dataPill(result.type, 'string')}`,
            }
        )
    }
)
